css:
.action-cluster {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
}

.tactile-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  background: var(--primary);
  color: var(--canvas);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: var(--radius-full, 9999px);
  padding: 0.65rem 1.35rem;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 4px 12px -2px rgba(0, 0, 0, 0.15), inset 0 1px 0 rgba(255, 255, 255, 0.25);
  transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.18s ease;
  outline: none;
}

.tactile-btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 16px -2px rgba(0, 0, 0, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.35);
}

.tactile-btn-primary:active {
  transform: scale(1.03, 0.94);
  box-shadow: 0 2px 6px -1px rgba(0, 0, 0, 0.15);
}

.tactile-btn-secondary {
  display: inline-flex;
  align-items: center;
  background: var(--surface);
  color: var(--text-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-full, 9999px);
  padding: 0.65rem 1.35rem;
  font-size: 0.9rem;
  font-weight: 500;
  cursor: pointer;
  transition: transform 0.18s cubic-bezier(0.34, 1.56, 0.64, 1), background-color 0.15s ease;
  outline: none;
}

.tactile-btn-secondary:hover {
  background: var(--canvas);
  transform: translateY(-1px);
}

.tactile-btn-secondary:active {
  transform: scale(1.02, 0.96);
}
